using System.Linq;
using AiLabs.Rules.Config;
using AiLabs.Rules.Core;
using AiLabs.Rules.Sim;
using AiLabs.Rules.State;
using AiLabs.Rules.Systems;
using AiLabs.SimTests.Support;
using Xunit;

namespace AiLabs.SimTests;

/// <summary>Q806–Q905: batch 17 sequel — rivals/chips (schema 31, grown local).</summary>
public class HatchRivalsChipsSequelLaterTests
{
    static ModelState M(Game g, int c) => new ModelState { Id = g.State.TakeId(), LineId = "mini", Capability = c, Status = ModelStatus.Released, Alignment = 500, Name = "S" };

    static void BuyAcquire(Game g, LabState r)
    {
        r.Models.Add(M(g, 510));
        r.Cash = -17_000;
        r.WeeksInDebt = 1;
        Finance.Earn(g.Me, LedgerLine.CapitalIn, 92_000_000);
        g.Do(Command.AcquireLab(g.Id, r.Id));
    }

    static int Hall(Game g, LabState lab)
    {
        int id = g.Do(Command.BuyLand(lab.Id, "us-oregon")).CreatedId;
        lab.Holding(id).HallKw = 450_000;
        return id;
    }

    [Fact] public void Q806_sequel_806() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4100, 8)); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 52_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); BuyAcquire(g, r); Assert.Single(g.Me.ChipOrders); }
    [Fact] public void Q807_sequel_807() { var g = Game.New(seed: 1431); var r = g.Rival("openaye"); r.Models.Add(M(g, 528)); r.Cash = -16_900; Finance.Earn(g.Me, LedgerLine.CapitalIn, 72_000_000); g.Do(Command.AcquireLab(g.Id, r.Id)); g.Refused(Command.OrderChips(r.Id, 1, HardwareBatch.Cloud, 1), CommandError.LabAbsorbed); }
    [Fact] public void Q808_sequel_808() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4600, 6)); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 44_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 1)); BuyAcquire(g, r); Assert.Equal(37, g.State.Schema); SaveSchemaPretend.AssertRoundTrip(g.Sim); }
    [Fact] public void Q809_sequel_809() { var g = Game.New(seed: 1433); var r = g.Rival("openaye"); r.Models.Add(M(g, 540)); r.Cash = -18_000; Finance.Earn(g.Me, LedgerLine.CapitalIn, 78_000_000); Assert.True(AcquisitionSystem.Quote(g.C, g.State, g.Me, r).Total > 0); }
    [Fact] public void Q810_sequel_810() { Game g = HatchFollowUpLaterTests.ChipListingSeller(); ChipDesign d = HatchFollowUpLaterTests.ReadyInferenceListing(g); g.Do(Command.SetChipListing(g.Id, d.Id, 4000, 10)); Finance.Earn(g.Me, LedgerLine.CapitalIn, 65_000_000); LabState r = HatchFollowUpLaterTests.OpenAyeBuyer(g, 75_000_000); g.Do(Command.BuyListedChips(r.Id, g.Id, d.Id, HardwareBatch.Cloud, 2)); BuyAcquire(g, r); Assert.True(LabQueries.ParticipatesInEconomy(g.Me)); }
